import{read,write}from './storage.js';
import{RECITERS,reciterInfo}from './quran-reciters.js';
let account=()=>({}),initialized=false;
const scope=()=>account().userId||'device';
export function validListeningPosition(p){return !!p&&Number.isInteger(p.surah)&&p.surah>=1&&p.surah<=114&&RECITERS.some(r=>r.id===p.reciter)&&Number.isInteger(p.index)&&p.index>=0&&p.index<286&&Number.isFinite(p.seconds)&&p.seconds>=0&&p.seconds<=86400&&Number.isFinite(p.updatedAt);}
export function readListeningPosition(){const p=read('quran-last-listening-v1:'+scope(),null);return validListeningPosition(p)?p:null;}
export function initQuranListeningProgress({playback,getAccount,now=Date.now}){if(initialized)return;initialized=true;account=getAccount;let last=null,lastSave=0,owner=null,signature='';const persist=()=>{if(last&&owner&&write('quran-last-listening-v1:'+owner,last))lastSave=now();};const sample=()=>{const s=playback.state;if(!s.surah||!s.reciter){persist();signature='';owner=null;return;}const key=s.reciter+':'+s.surah.number;if(key!==signature||s.status==='loading'&&signature===''){signature=key;owner=scope();}if(owner!==scope()||!['playing','paused','ended'].includes(s.status))return;const whole=reciterInfo(s.reciter).format==='surah';last={surah:s.surah.number,reciter:s.reciter,index:whole?0:s.index,ayah:s.ayah||s.index+1,seconds:s.trackPositionSeconds??s.positionSeconds??0,elapsed:s.positionSeconds||0,offlineOnly:s.offlineOnly===true,updatedAt:now()};if(validListeningPosition(last)&&(now()-lastSave>=3000||s.status!=='playing'))persist();};playback.subscribe(sample);setInterval(sample,1000);window.addEventListener('pagehide',()=>{sample();persist();});document.addEventListener('visibilitychange',()=>{if(document.hidden){sample();persist();}});}
